mapper.select:
select notice_id, title, content, created_at, is_pinned, admin_id, type, updated_at
from notice
where notice_id = #{noticeId}

mapper.update:
update notice
set is_pinned = 1 - is_pinned
where notice_id = #{noticeId}

update notice
set deleted = 1, updated_at = now()
where notice_id = #{noticeId}
